Input: {"question": "When was Tomorrow's World first broadcast?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0338-c06c70c62093:d00", "start": 0, "end": 107, "text": "Tomorrow's World Tomorrow's World is a BBC television series on new developments in science and technology."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0338-c06c70c62093:d00", "start": 108, "end": 218, "text": "First transmitted on 7 July 1965 on BBC1, it ran for 38 years until it was cancelled at the beginning of 2003."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0338-c06c70c62093:d00", "start": 219, "end": 317, "text": "The \"Tomorrow's World\" title was revived in 2017 as an umbrella brand for BBC science programming."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0338-c06c70c62093:d00", "start": 318, "end": 420, "text": "\"Tomorrow's World\" was created by Glyn Jones to fill a half-hour slot in the 1965 BBC summer schedule."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0338-c06c70c62093:d00", "start": 421, "end": 515, "text": "Jones and his wife conceived the show's name the night before the \"Radio Times\" went to press."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0338-c06c70c62093:d00", "start": 516, "end": 573, "text": "In its early days the show was edited by Max Morgan-Witts"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0338-c06c70c62093:d01", "start": 0, "end": 311, "text": "Judith Bunting Martin Mortimore Sam Starbuck David McNab Richard Collin Original release Network BBC1 Release 7 July 1965 ( 1965-7-7 ) – 16 July 2003 ( 2003-7-16 ) Related The Tomorrow 's World Roadshow Tomorrow 's World is a British television series about contemporary developments in science and technology ."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0338-c06c70c62093:d01", "start": 312, "end": 422, "text": "First broadcast on 7 July 1965 on BBC1 , it ran for 38 years until it was cancelled at the beginning of 2003 ."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0338-c06c70c62093:d01", "start": 423, "end": 521, "text": "The Tomorrow 's World title was revived in 2017 as an umbrella brand for BBC science programming ."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0338-c06c70c62093:d01", "start": 522, "end": 543, "text": "[ 1 ] [ 2 ] Content ["}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0338-c06c70c62093:d02", "start": 0, "end": 154, "text": "Premiering on 7 July 1965 , Tomorrow ’ s World was designed to showcase scientific invention and there are two main reasons why so many viewers tuned in ."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0338-c06c70c62093:d02", "start": 155, "end": 340, "text": "One was in the hope that one of the live experiments would go wrong ( they frequently did ) , and the other was because , for many years , it was on immediately before Top of the Pops ."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0338-c06c70c62093:d02", "start": 341, "end": 408, "text": "So youngsters would plough through Raymond Baxter just to get to T."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0338-c06c70c62093:d02", "start": 409, "end": 423, "text": "Rex or Slade ."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0338-c06c70c62093:d02", "start": 424, "end": 490, "text": "Baxter , a former WWII pilot , was the mainstay of the show for 12"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0338-c06c70c62093:d03", "start": 0, "end": 90, "text": "Tomorrow's World is a BBC television series on new developments in science and technology."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0338-c06c70c62093:d03", "start": 91, "end": 204, "text": "First transmitted on 15 August 1966 on BBC1, it ran for 38 years until it was cancelled at the beginning of 2003."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0338-c06c70c62093:d03", "start": 205, "end": 303, "text": "The \"Tomorrow's World\" title was revived in 2017 as an umbrella brand for BBC science programming."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0338-c06c70c62093:d03", "start": 304, "end": 406, "text": "\"Tomorrow's World\" was created by Glyn Jones to fill a half-hour slot in the 1966 BBC summer schedule."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0338-c06c70c62093:d03", "start": 407, "end": 501, "text": "Jones and his wife conceived the show's name the night before the \"Radio Times\" went to press."}, "D4S6": {"document_number": 4, "doc_id": "ramdocs-0338-c06c70c62093:d03", "start": 502, "end": 560, "text": "In its early days the show was edited by Max Morgan-Witts."}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0338-c06c70c62093:d04", "start": 0, "end": 308, "text": "Judith Bunting Martin Mortimore Sam Starbuck David McNab Richard Collin Original release Network BBC1 Release 15 August 1970 (1970-8-15) – 16 July 2003 (2003-7-16) Related The Tomorrow's World Roadshow Tomorrow's World is a British television series about contemporary developments in science and technology."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0338-c06c70c62093:d04", "start": 309, "end": 420, "text": "First broadcast on 15 August 1970 on BBC1, it ran for 33 years until it was cancelled at the beginning of 2003."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0338-c06c70c62093:d04", "start": 421, "end": 517, "text": "The Tomorrow's World title was revived in 2017 as an umbrella brand for BBC science programming."}, "D5S4": {"document_number": 5, "doc_id": "ramdocs-0338-c06c70c62093:d04", "start": 518, "end": 535, "text": "[1] [2] Content ["}, "D6S1": {"document_number": 6, "doc_id": "ramdocs-0338-c06c70c62093:d05", "start": 0, "end": 102, "text": "Tomorrow's World (1959 TV series) Tomorrow's World is a 1959 Australian educational television series."}, "D6S2": {"document_number": 6, "doc_id": "ramdocs-0338-c06c70c62093:d05", "start": 103, "end": 178, "text": "Intended to be viewed in schools, it aired on ABC in a 20-minute time-slot."}